-- 001 Grundschema (Tabellen, Rechte, Zeilen-Sicherheit RLS, Storage, Startdaten)
-- Hinweis: Wurde schrittweise im SQL-Editor aufgebaut; diese Datei fasst die Grundlagen zusammen.
create table if not exists admins(email text primary key);
insert into admins values ('kleinenzaigen123@gmail.com') on conflict do nothing;
create or replace function is_admin() returns boolean language sql stable as $$ select exists(select 1 from admins where email = (auth.jwt()->>'email')) $$;
create table if not exists products(id bigint primary key generated always as identity, name text not null, kat text, preis numeric not null, aktion numeric default 0, neu boolean default false, beschr text, material text, farben jsonb default '[]', form text default 'sofa', sort int default 0, created_at timestamptz default now());
create table if not exists settings(id int primary key default 1 check(id=1), aktion jsonb, hero jsonb);
create table if not exists orders(id text primary key, user_id uuid default auth.uid(), email text, name text, items jsonb, total numeric, lv text, ort text, zh text, status int default 0, created_at timestamptz default now());
create table if not exists visits(id bigint generated always as identity primary key, path text, t timestamptz default now());
alter table admins enable row level security; alter table products enable row level security; alter table settings enable row level security; alter table orders enable row level security; alter table visits enable row level security;
create policy "read products" on products for select using (true);
create policy "admin write products" on products for all using (is_admin()) with check (is_admin());
create policy "read settings" on settings for select using (true);
create policy "admin write settings" on settings for all using (is_admin()) with check (is_admin());
create policy "own orders insert" on orders for insert to authenticated with check (user_id = auth.uid());
create policy "own orders read" on orders for select to authenticated using (user_id = auth.uid() or is_admin());
create policy "admin orders update" on orders for update using (is_admin());
create policy "visits insert" on visits for insert with check (true);
create policy "admin visits read" on visits for select using (is_admin());
insert into storage.buckets(id,name,public) values('photos','photos',true) on conflict do nothing;
create policy "photos public read" on storage.objects for select using (bucket_id='photos');
create policy "photos admin write" on storage.objects for insert with check (bucket_id='photos' and is_admin());
create policy "photos admin update" on storage.objects for update using (bucket_id='photos' and is_admin());
create policy "photos admin delete" on storage.objects for delete using (bucket_id='photos' and is_admin());
insert into settings(id,aktion,hero) values (1,'{"aktiv":true,"text":"Frühjahrsaktion: 15 % auf alle Polsterservice-Aufträge bis 31.03.","link":"#polsterei"}','{"titel":"Polstermöbel, die zu Ihnen passen.","text":"Sofas, Sessel und Betten aus unserer Ausstellung – und die eigene Polsterei für Neubezug und Reparatur.","bild":"img/hero.jpg"}') on conflict do nothing;
create or replace function is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from admins where email = (auth.jwt()->>'email')) $$;
grant usage on schema public to anon, authenticated;
grant select on products, settings to anon, authenticated;
grant insert, update, delete on products, settings to authenticated;
grant insert on visits to anon, authenticated;
grant select on visits to authenticated;
grant select, insert, update on orders to authenticated;
grant execute on function is_admin() to anon, authenticated;
insert into admins values ('demo@polsterhaus-muster.de') on conflict do nothing;
alter table products add column if not exists masse text, add column if not exists pflege text, add column if not exists lieferzeit text default '2 bis 3 Wochen';
create table if not exists samples(id bigint generated always as identity primary key, name text, email text, adresse text, produkt text, farbe text, created_at timestamptz default now());
create table if not exists termine(id bigint generated always as identity primary key, name text, telefon text, wunsch text, nachricht text, created_at timestamptz default now());
create table if not exists reviews(id bigint generated always as identity primary key, product_id bigint, name text, sterne int check(sterne between 1 and 5), text text, demo boolean default false, created_at timestamptz default now());
alter table samples enable row level security; alter table termine enable row level security; alter table reviews enable row level security;
create policy "samples insert" on samples for insert with check (true);
create policy "samples admin read" on samples for select using (is_admin());
create policy "termine insert" on termine for insert with check (true);
create policy "termine admin read" on termine for select using (is_admin());
create policy "reviews read" on reviews for select using (true);
create policy "reviews insert" on reviews for insert to authenticated with check (true);
create policy "reviews admin delete" on reviews for delete using (is_admin());
grant insert on samples, termine to anon, authenticated; grant select on samples, termine to authenticated;
grant select on reviews to anon, authenticated; grant insert on reviews to authenticated; grant delete on reviews to authenticated;
update products set masse='Breite 215 cm, Tiefe 95 cm, Höhe 85 cm, Sitzhöhe 45 cm', pflege='Fleckenentfernung mit lauwarmem Wasser und mildem Reiniger, nicht chemisch reinigen.' where name like 'Sofa Lindau%';
