insert into reviews(product_id,name,sterne,text,demo) select id,'Beispiel-Kunde A',5,'Bequemes Sofa, die Farbe entspricht dem Muster. (Demo-Bewertung)',true from products where name like 'Sofa Lindau%';
insert into reviews(product_id,name,sterne,text,demo) select id,'Beispiel-Kunde B',4,'Schnelle Lieferung, Aufbau einfach. (Demo-Bewertung)',true from products where name like 'Sofa Lindau%';
